// Base64 Encode/Decode
// Pure JavaScript implementation for Jint runtime

var mode = input.get("mode") || "encode";
var inputText = input.get("inputText");

// Base64 character set
var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function btoa(str) {
    var output = "";
    for (var i = 0; i < str.length; i += 3) {
        var c1 = str.charCodeAt(i);
        var c2 = i + 1 < str.length ? str.charCodeAt(i + 1) : 0;
        var c3 = i + 2 < str.length ? str.charCodeAt(i + 2) : 0;

        var e1 = c1 >> 2;
        var e2 = ((c1 & 3) << 4) | (c2 >> 4);
        var e3 = ((c2 & 15) << 2) | (c3 >> 6);
        var e4 = c3 & 63;

        if (i + 1 >= str.length) {
            e3 = 64;
            e4 = 64;
        } else if (i + 2 >= str.length) {
            e4 = 64;
        }

        output += chars.charAt(e1) + chars.charAt(e2);
        output += e3 === 64 ? "=" : chars.charAt(e3);
        output += e4 === 64 ? "=" : chars.charAt(e4);
    }
    return output;
}

function atob(str) {
    str = str.replace(/=+$/, "");
    var output = "";
    for (var i = 0; i < str.length; i += 4) {
        var e1 = chars.indexOf(str.charAt(i));
        var e2 = chars.indexOf(str.charAt(i + 1));
        var e3 = i + 2 < str.length ? chars.indexOf(str.charAt(i + 2)) : 0;
        var e4 = i + 3 < str.length ? chars.indexOf(str.charAt(i + 3)) : 0;

        var c1 = (e1 << 2) | (e2 >> 4);
        var c2 = ((e2 & 15) << 4) | (e3 >> 2);
        var c3 = ((e3 & 3) << 6) | e4;

        output += String.fromCharCode(c1);
        if (i + 2 < str.length + (str.length % 4 ? 4 - str.length % 4 : 0) - 1) {
            output += String.fromCharCode(c2);
        }
        if (i + 3 < str.length + (str.length % 4 ? 4 - str.length % 4 : 0) - 1) {
            output += String.fromCharCode(c3);
        }
    }
    return output;
}

if (!inputText && inputText !== "") {
    log.error("Input text is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Input text is required");
    output.set("Result", "");
    tags.trigger("error");
} else {
    try {
        var result = "";

        if (mode.toLowerCase() === "decode") {
            result = atob(inputText);
            log.info("Decoded Base64 (" + inputText.length + " chars) to text (" + result.length + " chars)");
        } else {
            result = btoa(inputText);
            log.info("Encoded text (" + inputText.length + " chars) to Base64 (" + result.length + " chars)");
        }

        output.set("Result", result);
        output.set("InputLength", inputText.length);
        output.set("OutputLength", result.length);
        output.set("Mode", mode.toLowerCase() === "decode" ? "decode" : "encode");
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");
        tags.trigger("success");

    } catch (ex) {
        log.error("Base64 operation failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Base64 " + mode + " failed: " + ex.message);
        output.set("Result", "");
        tags.trigger("error");
    }
}
